<?php $view->extend('layouts.admin');$view->section('content');?><div class="aho-admin-page"><div class="aho-admin-page__header"><div><h1>🤖 AI Asistan</h1><p>Admin işlemleri hakkında yardım alın.</p></div></div><div class="aho-card" style="max-width:850px"><div id="aiMessages" style="min-height:300px;max-height:480px;overflow:auto;padding:12px;background:var(--aho-color-ink-50);border-radius:8px;margin-bottom:14px"><div><strong>AI:</strong> Merhaba. Ürün, müşteri, sipariş ve sistem işlemleri hakkında yardımcı olabilirim.</div></div><form id="aiAdminForm" style="display:flex;gap:8px"><?=csrf()?><input id="aiAdminInput" class="aho-form-input" placeholder="Örn: müşterileri göster" autocomplete="off"><button class="aho-btn aho-btn--primary">Gönder</button></form></div></div><script>document.getElementById('aiAdminForm').addEventListener('submit',async e=>{e.preventDefault();let i=document.getElementById('aiAdminInput'),m=document.getElementById('aiMessages'),v=i.value.trim();if(!v)return;m.insertAdjacentHTML('beforeend','<p><strong>Siz:</strong> '+v.replace(/</g,'&lt;')+'</p>');i.value='';let r=await fetch('/ai/admin',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({message:v,_csrf:document.querySelector('[name=_csrf]').value})});let d=await r.json();m.insertAdjacentHTML('beforeend','<p><strong>AI:</strong> '+String(d.reply||d.error||'Yanıt alınamadı').replace(/</g,'&lt;')+'</p>');m.scrollTop=m.scrollHeight});</script><?php $view->endSection();?>